export const matriz = {
  servicio: "Amazon EC2",
  filas: [
    { tarea: "Seguridad física de las instalaciones", responsable: "AWS" },
    { tarea: "Hardware y capa de virtualización", responsable: "AWS" },
    { tarea: "Parches del sistema operativo invitado", responsable: "CLIENTE" },
    { tarea: "Software de aplicación instalado en las instancias", responsable: "CLIENTE" },
    { tarea: "Configuración del grupo de seguridad", responsable: "CLIENTE" },
  ],
};

spec.code:
const fila = matriz.filas.find((f) => f.tarea === "Parches del sistema operativo invitado");
assert.ok(fila, "debe existir la fila de parches");
assert.strictEqual(fila.responsable, "CLIENTE");

for (const fila of matriz.filas) {
  assert.ok(["AWS", "CLIENTE"].includes(fila.responsable), fila.tarea + " tiene un responsable no válido");
}

const esperado = {
  "Seguridad física de las instalaciones": "AWS",
  "Hardware y capa de virtualización": "AWS",
  "Software de aplicación instalado en las instancias": "CLIENTE",
  "Configuración del grupo de seguridad": "CLIENTE",
};
for (const [tarea, responsable] of Object.entries(esperado)) {
  const fila = matriz.filas.find((f) => f.tarea === tarea);
  assert.ok(fila, tarea + " debe seguir existiendo");
  assert.strictEqual(fila.responsable, responsable);
}

