export type Servicio = "Amazon EC2" | "Amazon S3" | "Amazon DynamoDB";

const TAREAS_COMUNES: string[] = [
  "Gestionar los datos y sus opciones de cifrado",
  "Clasificar los activos",
  "Aplicar permisos con IAM",
];

const TAREAS_DE_EC2: string[] = [
  "Administrar el sistema operativo invitado y sus parches",
  "Administrar el software de aplicación instalado",
  "Configurar el grupo de seguridad",
];

export function tareasDelCliente(servicio: Servicio): string[] {
  const tareas = [...TAREAS_COMUNES];
  if (servicio === "Amazon EC2") {
    tareas.push(...TAREAS_DE_EC2);
  }
  return tareas;
}

spec.code:
tareasDelCliente("Amazon EC2");
assert.deepStrictEqual(tareasDelCliente("Amazon S3"), [
  "Gestionar los datos y sus opciones de cifrado",
  "Clasificar los activos",
  "Aplicar permisos con IAM",
]);

const tareas = tareasDelCliente("Amazon EC2");
assert.strictEqual(tareas.length, 6);
assert.ok(tareas.includes("Configurar el grupo de seguridad"));
